 x=dict(id='L49-ISSUE-'+key,sourceId='lectures',sourceSha256=SHA,physicalPage=p,finding=claim,handling=basis,method=method,primaryEvidence=list(primary),status='qualified_pending_independent_review');ISS.append(x);return x
