def fm(e,v,u,a=()):return dict(expression=e,variables=v,units=u,assumptions=list(a))
def ask(p,tag,stem,opts,why,*,kind='conceptual',difficulty='easy',ass=(),steps=(),formulas=(),cites=None,conflict=None,primary=(),correct=(0,)):
 cid=f'{B}-C-{tag}';c=CM[cid];qid=f'{B}-P{p}-Q{1+sum(q["id"].startswith(f"{B}-P{p}-Q")for q in Q):02}'
 assert len(opts)==len(why)and len(set(opts))==len(opts)
 if cites is None:cites=[(p,'statement',LOC[p])]
 cc=[dict(slideId=f'lectures-p{page}',sourceId='lectures',sourceSha256=SHA,physicalPage=page,kind=ck,locator=f'Printed slide {page-1536}: {loc}',evidenceText=T[page],role='conflict'if conflict and page==conflict['physicalPage']else'premise'if kind in ['numerical','synthesis','algorithm_trace']else'explicit',region=None)for page,ck,loc in cites]
 oo=[dict(id=f'o{i+1}',text=x)for i,x in enumerate(opts)];shift=int(hashlib.sha256(qid.encode()).hexdigest()[:4],16)%len(oo);oo=oo[shift:]+oo[:shift];just=' '.join(why[i]for i in correct)
 q=dict(id=qid,version=1,status='draft',authorId=A,stem=stem,selectionMode='multi'if len(correct)>1 else'single',type=kind,difficulty=difficulty,cognitiveSkill='numerical'if kind=='numerical'else'algorithm'if kind=='algorithm_trace'else'synthesis'if kind=='synthesis'else'application'if kind in ['scenario','diagram']else'recall'if kind=='definition'else'conceptual',week=10,lectureId='L49',topic='Conversational AI & Human-Robot Interaction',subtopic=c['title'],tags=['conversational-ai',tag],conceptIds=[cid],assumptions=list(ass),options=oo,correctOptionIds=[f'o{i+1}'for i in correct],citations=cc,solution=dict(justification=just,optionExplanations={f'o{i+1}':('Correct. 'if i in correct else'Incorrect. ')+w for i,w in enumerate(why)},steps=list(steps),formulas=list(formulas),simpleExplanation=just,memoryAid=None,misconceptions=[why[i]for i in range(len(opts))if i not in correct],examTraps=[],prerequisiteConceptIds=[]),origin='generated',reviewIds=[])
 if len(opts)<4:q['optionCountRationale']='Only distinct plausible technical alternatives are used; filler is omitted.'
 if conflict:
  q['conflictResolution']=dict(status='explicit-qualification-pending-independent-review',questionVersion=1,sourceId='lectures',sourceSha256=SHA,physicalPage=conflict['physicalPage'],sourceClaim=conflict['finding'],basis=conflict['handling'],method=conflict['method'],sourceIssueId=conflict['id'],scope='This version only; independent review required.')
  primary=list(primary)+[x for x in conflict['primaryEvidence']if x not in primary]
 if primary:q['primaryEvidence']=list(primary)
 Q.append(q);c['questionIds'].append(qid);c['status']='drafted';return q
def save():
 base.update(questions=Q,concepts=C,coverageNote=f'{len(Q)} PDF-based drafts; all 29 pages actually inspected. Official notebook retrieval blocked; no fresh model inference or original notebook outputs claimed. Independent review pending.')
 write(f'data/question-batches/{B}.json',base);write(f'audits/source-disputes-{B}.json',ISS);print('Saved',len(Q),'drafts',flush=True)

# Foundations and bounded historical taxonomy.
ask(1539,'asr-intent','A robot transcribes “bring the cup” correctly but chooses the wrong task. Which distinction explains this failure?', ['Recognizing words and interpreting the intended task are separate functions','Correct transcription necessarily identifies the executable task, so only TTS can be wrong','Conversational interpretation produces the waveform, while ASR selects the task','ASR evaluates motion feasibility after the task has been selected'],['ASR can succeed while intent interpretation fails.','TTS concerns generated speech; a correct transcript does not establish the correct task.','These are not the roles of interpretation and recognition.','Motion validation is distinct from acoustic transcription.'],kind='scenario')
ask(1539,'asr-intent','What does the slide’s ear-versus-brain analogy primarily distinguish?', ['Speech recognition from intent interpretation and response formulation','Input speech synthesis from output speech recognition','Phoneme storage from the robot’s motor torque calculation','Two alternative names for the same transcript-only operation'],['The analogy separates recognizing speech from conversational processing.','This reverses input recognition and output synthesis.','Torque computation is not the analogy’s conversational role.','Interpretation and response formulation go beyond producing a transcript.'])
ask(1540,'evolution','Which sequence matches the lecture’s broad timeline, without asserting exact invention dates?', ['ELIZA rules → ALICE patterns → commercial assistants → Transformers → ChatGPT era','ALICE patterns → ELIZA rules → Transformers → commercial assistants → ChatGPT era','ELIZA rules → commercial assistants → ALICE patterns → ChatGPT era → Transformers','ELIZA rules → ALICE patterns → ChatGPT era → Transformers → commercial assistants'],['This follows the displayed left-to-right historical progression.','ALICE follows ELIZA, and the timeline places commercial assistants before Transformers.','The ALICE and ChatGPT placements contradict the diagram.','The late timeline stages are reversed.'],kind='sequence',cites=[(1540,'figure','Entire timeline, ELIZA 1964 through ChatGPT era 2022+')])
ask(1540,'evolution','The timeline calls ALICE retrieval-based. What is the justified interpretation when read with the AIML slides?', ['It can select authored templates using patterns; dense-vector nearest-neighbor retrieval is not thereby established','It must encode every input as a dense vector because every stored-response method uses that algorithm','It must generate every response from newly sampled neural tokens because it remembers context','It cannot retain any conversational predicate because response templates are stored'],['The lecture’s later pattern/template examples specify the mechanism more narrowly.','Stored responses do not uniquely determine a vector-search implementation.','Context predicates can be maintained by rule systems.','State and stored response templates can coexist.'],cites=[(1540,'figure','ALICE retrieval-based timeline label'),(1547,'statement','Keywords, response patterns and stored phrase database'),(1548,'statement','AIML category and think descriptions')],conflict=HIST)
ask(1541,'turing','In the lecture’s text-based Turing-test setup, what evidence does the judge use?', ['Conversation with hidden participants, without directly seeing which is the machine','Inspection of the participants’ source code before asking questions','Measurement of the robot’s physical resemblance to a person','The machine’s claimed identity rather than its conversational behavior'],['The illustrated test evaluates behavior through the exchange.','Source-code inspection is not the stated judging channel.','Physical appearance is excluded by the hidden text-based setup.','A claim alone is not the conversational evidence being evaluated.'],kind='definition',cites=[(1541,'figure','Judge communicating with hidden human and machine'),(1541,'statement','Text-conversation indistinguishability criterion')])
ask(1541,'turing','Suppose a judge cannot reliably distinguish the two participants in the stipulated test. What follows most directly?', ['Their responses were difficult to distinguish in that test, not proof of an inner emotional state','The machine necessarily understands every possible topic outside the test','The machine has been shown to have the same subjective experiences as the human','The machine’s responses must have been generated without any stored templates'],['The evidence concerns observed performance under the test conditions.','Performance on a finite interaction does not establish universal capability.','Behavioral indistinguishability does not directly measure subjective experience.','The result alone does not identify the implementation.'],kind='scenario',ass=['No additional implementation or internal-state evidence is supplied.'])
ask(1542,'chatbot-interface','Which function makes the depicted weather chatbot a conversational interface?', ['It accepts a language request and provides a language response','It stores a weather table even if no user interaction exists','It measures atmospheric pressure without accepting any request','It converts every weather answer directly into a motor trajectory'],['The request-response language exchange forms the communication layer.','A database alone is not the depicted interactive interface.','A sensor alone need not be conversational.','Language responses are not inherently motor trajectories.'],kind='diagram',cites=[(1542,'figure','Weather question and textual answer exchange')])
ask(1542,'chatbot-interface','Which grouping correctly separates interaction channel from chatbot implementation?', ['Text or speech are channels; rules, retrieval and generation are response mechanisms','Text means rule-based; speech means generative, with no other combinations','Rules and retrieval are audio formats; generation is a microphone type','A speech channel proves that the chatbot directly models audio without ASR'],['A channel does not uniquely fix the response mechanism.','Rule systems can use speech interfaces and generators can use text.','These terms describe response selection or creation, not audio hardware.','Speech interaction may use an ASR/text/TTS cascade.'],cites=[(1542,'statement','Text or speech interaction definition'),(1543,'statement','Rule-based chatbot heading'),(1546,'statement','Retrieval-based chatbot heading'),(1551,'statement','Generative chatbot heading')])
ask(1543,'rules','In the displayed rule-found flowchart, what happens when pattern matching finds no applicable rule?', ['Return the specified fallback response','Train a new response rule automatically from that unmatched input','Choose a neural next-token continuation in the same rule-only diagram','Execute the nearest physical action without a matching intent'],['The no branch leads to the shown fallback.','No training operation is drawn.','No neural generator is part of this fixed-rule flowchart.','The diagram returns conversational output, not an unmatched robot action.'],kind='diagram',cites=[(1543,'figure','Rule Found? no branch to Sorry, I did not get you fallback')])
ask(1543,'rules','A supplied rule matches only the exact normalized input hello. Normalization lowercases and trims surrounding spaces, but does not remove punctuation. Which input triggers it?', [' HELLO ','hello!','say hello','hello there'],['Lowercasing and trimming produces hello.','The exclamation mark remains and prevents exact equality.','The additional word remains.','The additional word remains.'],kind='algorithm_trace',ass=['Only the stated exact-match rule and normalization are available.'],steps=['Strip surrounding spaces.','Lowercase the result.','Compare the entire resulting string with hello.'],cites=[(1543,'code','IF input = hello THEN greeting response')])
ask(1543,'rules','Which statement avoids overgeneralizing the limitations of the slide’s stateless rule example?', ['Rules may retain explicitly programmed state, even though this example does not learn new rules from dialogue','Any rule system with a state variable must have trained neural weights','A wildcard rule is necessarily unable to match a previously unseen surface sentence','Adding a remembered variable guarantees general language understanding'],['State can be represented by variables without data-driven model training.','A variable is not evidence of neural training.','Wildcards can cover multiple surface strings.','State retention alone does not guarantee broad understanding.'],conflict=RULE,cites=[(1543,'statement','No-context/no-learning limitation bullets'),(1550,'code','Hidden topic and personality setters')])
