# Author quality pass: replace unrelated filler with parallel, same-domain misconceptions.
QM={q['id']:q for q in Q}
def refine(suffix,opts,why,stem=None,correct=(0,)):
 q=QM[B+'-'+suffix]
 if stem:q['stem']=stem
 oo=[dict(id=f'o{i+1}',text=t)for i,t in enumerate(opts)];shift=int(hashlib.sha256(q['id'].encode()).hexdigest()[:4],16)%len(oo);q['options']=oo[shift:]+oo[:shift]
 q['correctOptionIds']=[f'o{i+1}'for i in correct];q['selectionMode']='multi'if len(correct)>1 else'single';just=' '.join(why[i]for i in correct)
 q['solution'].update(justification=just,simpleExplanation=just,optionExplanations={f'o{i+1}':('Correct. 'if i in correct else'Incorrect. ')+w for i,w in enumerate(why)},misconceptions=[why[i]for i in range(len(why))if i not in correct])
 if len(opts)<4:q['optionCountRationale']='Three distinct technical interpretations suffice; no unrelated filler option is added.'
